import{_ as i,a0 as l,w as d,s as p,ao as s,I as a,x as t,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何從Linux命令列截屏 | LCTT x X-CMD","titleTemplate":false,"description":"如何從Linux命令列截屏 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從Linux命令列截屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從Linux命令列截屏 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to take a screenshot from the command line on Linux","title":"如何從Linux命令列截屏","tag":"201406","desc":""},"relativePath":"201406/How to take a screenshot from the command line on Linux.md","filePath":"[post].md"}'),m={name:"201406/How to take a screenshot from the command line on Linux.md"};function c(u,e,h,x,f,_){const o=l("Link");return d(),p("div",null,[e[14]||(e[14]=s(`<h1 id="如何從linux命令列截屏" tabindex="-1">如何從Linux命令列截屏 <a class="header-anchor" href="#如何從linux命令列截屏" aria-label="Permalink to “如何從Linux命令列截屏”">​</a></h1><p>Linux上有着許多不同口味兒的截屏工具，包括桌面環境專用的截屏程序（如： KDE裏面的KSnapshot，GNOME裏面的gnome-screenshot，Xfce的Screenshooter），或者是通用的截屏程序（如 Shutter）。而Scort（&quot;SCReen shOT&quot;的縮寫）是最獨一無二的截屏工具之一，它是一個<strong>命令列截屏工具</strong>。雖然它的界面十分簡約，但Scrot在功能上和其它專用的基於GUI的屏幕捕獲工具一樣強大。舉個例子，Scrot支持延時截屏，截屏調整品質/大小，命令列傳遞等功能。如果你是那些熱衷命令列的愛好者之一，Scrot應該是你加入兵器庫中的又一實用工具。在這個教程中，我將會描述<strong>如何在命令列中用Scrot截屏</strong>。</p><h3 id="在linux中安裝scrot" tabindex="-1">在Linux中安裝Scrot <a class="header-anchor" href="#在linux中安裝scrot" aria-label="Permalink to “在Linux中安裝Scrot”">​</a></h3><p>在 Debian，Ubuntu 或 Linux Mint 上安裝Scrot：</p><pre><code>$ sudo apt-get install scrot
</code></pre><p>在 Fedora 上安裝Scrot：</p><pre><code>$ sudo yum install scrot
</code></pre><p>要在CentOS上安裝Scrot，你可以按照下列步驟從源碼編譯：</p>`,8)),a("p",null,[e[1]||(e[1]=t("首先",-1)),r(o,{href:"http://xmodulo.com/2013/01/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:n(()=>[...e[0]||(e[0]=[t("在CentOS上啓用Repoforge",-1)])]),_:1}),e[2]||(e[2]=t("，然後使用下列命令：",-1))]),e[15]||(e[15]=s(`<pre><code>$ sudo yum install giblib-devel
$ wget http://linuxbrit.co.uk/downloads/scrot-0.8.tar.gz
$ tar xvfvz scrot-0.8.tar.gz
$ cd scrot-0.8
$ ./configure
$ make
$ sudo make install
</code></pre><h3 id="用scrot截屏" tabindex="-1">用Scrot截屏 <a class="header-anchor" href="#用scrot截屏" aria-label="Permalink to “用Scrot截屏”">​</a></h3><p>在這個教程的下面的部分，我會描述如何通過幾種不同方法用Scrot截屏。</p><h4 id="_1-截下整個桌面" tabindex="-1">1. 截下整個桌面 <a class="header-anchor" href="#_1-截下整個桌面" aria-label="Permalink to “1. 截下整個桌面”">​</a></h4><p>截取整個桌面十分簡單。只需運行Scrot命令，不需要任何參數，然後它會保存一張整個桌面的截屏，以(日期標記).png的文件形式保存在當前文件目錄下。</p><pre><code>$ scrot
</code></pre><p>你也可以指定保存目標文件夾和截圖文件名。</p><pre><code>$ scrot ~/Pictures/my_desktop.png
</code></pre><h4 id="_2-截取特定窗口或矩形區域" tabindex="-1">2. 截取特定窗口或矩形區域 <a class="header-anchor" href="#_2-截取特定窗口或矩形區域" aria-label="Permalink to “2. 截取特定窗口或矩形區域”">​</a></h4><p>Scrot允許你在桌面選擇一個特定的窗口或定義一個矩形區域來截圖。使用下列命令來實現：</p><pre><code>$ scrot -s
</code></pre><p>運行這個命令後，繼續用你的鼠標單擊任意窗口或畫出一個矩形，它能夠觸發對選定窗口/區域的屏幕截取。（LCTT譯註，還要使用鼠標，伐快樂）</p><p>有時候你選定的區域或窗口可能會被桌面的其它窗口部分遮擋。在這種情況下，你在截屏前需要一點時間來清理那個部分。那正是延遲截屏能夠幫到你的，就像下面所描述的那樣。</p><h4 id="_3-延遲截屏" tabindex="-1">3. 延遲截屏 <a class="header-anchor" href="#_3-延遲截屏" aria-label="Permalink to “3. 延遲截屏”">​</a></h4><p>延遲截取在各種情況下都很實用。就在截圖前，你可能想要移動一下窗口，激活一下菜單，或是觸發特定時間（如通知）等等。 使用“-d N”參數，我們可以將截屏進程延遲N秒。</p><pre><code>$ scrot -s -d 5
</code></pre><h4 id="_4-調整截屏質量" tabindex="-1">4. 調整截屏質量 <a class="header-anchor" href="#_4-調整截屏質量" aria-label="Permalink to “4. 調整截屏質量”">​</a></h4><p>你可以在1到100的範圍內調整截取的圖像質量（數字越大質量越高）。默認質量設置為75。</p><pre><code>$ scrot -q 50
</code></pre><h4 id="_5-調整截屏尺寸" tabindex="-1">5. 調整截屏尺寸 <a class="header-anchor" href="#_5-調整截屏尺寸" aria-label="Permalink to “5. 調整截屏尺寸”">​</a></h4><p>你可以在1到100的範圍內調整截取的圖像尺寸（數字越大尺寸越大）。減小截屏的尺寸到原圖的10％：</p><pre><code>$ scrot -t 10
</code></pre><h4 id="_6-將截取的截屏傳遞給其它命令" tabindex="-1">6. 將截取的截屏傳遞給其它命令 <a class="header-anchor" href="#_6-將截取的截屏傳遞給其它命令" aria-label="Permalink to “6. 將截取的截屏傳遞給其它命令”">​</a></h4><p>Scrot允許你發送保存的截屏圖像給任意一個命令作為它們的輸入。這個選項在你想對截屏圖像做任意後期處理的時候十分實用。截屏的文件名/路徑跟隨於“$f”字符串之後。</p><pre><code>$ scrot -e &#39;mv $f ~/screenshots&#39;
</code></pre><hr>`,26)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),r(o,{href:"http://xmodulo.com/2014/05/take-screenshot-command-line-linux.html"},{default:n(()=>[...e[3]||(e[3]=[t("http://xmodulo.com/2014/05/take-screenshot-command-line-linux.html",-1)])]),_:1})]),a("p",null,[e[7]||(e[7]=t("譯者：",-1)),r(o,{href:"https://github.com/alim0x"},{default:n(()=>[...e[5]||(e[5]=[t("alim0x",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const L=i(m,[["render",c]]);export{b as __pageData,L as default};
